export function createState(seed=Date.now()){return {version:2,saveVersion:4,activeResearch:null,researchCredits:0,stats:freshStats(0),encounters:{},fastestSentence:null,bestValueSentence:null,seed:seed>>>0||123456789,nextId:2,gold:800,rp:0,time:0,savedAt:Date.now(),paused:false,speed:1,tier:0,goal:0,unlocks:[],research:[],achievements:[],onboarding:0,onboardDone:false,counts:{dust:0,letters:0,words:0,validWords:0,sentences:0,sold:0},discovered:[],recent:[],record:null,longestWord:'',fastest100:null,history:[],events:[],machines:[machine('gold',3,4,0,1)]}}
export function machine(type,x,y,dir=0,id=1){return{id,type,x,y,dir,buf:[],out:null,reject:null,progress:0,mode:type==='word'?'raw':'all',target:'auto',length:type==='phrase'?3:3,accent:'acute',punct:'.',filter:'vowel',custom:'ae',storage:'keep',level:1,paid:TYPES[type].cost,turn:0,made:0,work:0,age:0,events:[],note:'',disabled:false,template:'simple',lastResult:null,legacyCompact:false}}
function rng(s){s.seed^=s.seed<<13;s.seed^=s.seed>>>17;s.seed^=s.seed<<5;return(s.seed>>>0)/4294967296}
function shuffle(s,text){const a=Array.from(text);for(let i=a.length-1;i>0;i--){const j=Math.floor(rng(s)*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a.join('')}
export function capacity(s,m){let n=['chest','vault'].includes(m.type)?80:m.type==='buffer'?48:m.type==='word'?64:m.type==='phrase'?Math.max(16,maxWords(s)*2):['belt','fastbelt'].includes(m.type)?1:12;return n*(['chest','vault','buffer'].includes(m.type)&&s.research.includes('storage')?2:1)}
export function maxWords(s){return s.research.includes('mega')?2048:s.research.includes('long')?128:s.research.includes('syntax')?32:8}
export function period(s,m){let p=TYPES[m.type].period/Math.pow(1.4,m.level-1);if(m.type==='dust'&&s.research.includes('drills'))p/=2;if(['word','phrase'].includes(m.type)&&s.research.includes('assembly'))p/=2;return Math.max(STEP,p)}
export const pressCost=s=>s.research.includes('press')?2:3;
export function price(s,type){return Math.ceil(TYPES[type].cost*Math.pow(1.12,s.machines.filter(m=>m.type===type).length))}
export function placementError(s,m,ignoreId=null){if(!TYPES[m.type]||!Number.isInteger(m.x)||!Number.isInteger(m.y)||!Number.isInteger(m.dir)||m.dir<0||m.dir>3)return'Placement invalide.';return geometryIssue(s,m,ignoreId)}
export function place(s,type,x,y,dir=0){if(!TYPES[type]||!unlocked(s,type))return'Bâtiment encore verrouillé.';const m=machine(type,x,y,dir,s.nextId),error=placementError(s,m);if(error)return error;const cost=price(s,type);if(s.gold<cost)return`Il manque ${cost-Math.floor(s.gold)} pièces.`;s.nextId++;m.paid=cost;s.gold-=cost;s.machines.push(m);return m}
export function reposition(s,m,x,y,dir=m.dir){const next={...m,x,y,dir},error=placementError(s,next,m.id);if(error)return error;Object.assign(m,{x,y,dir});return null}
const upgradeResearch=['automation','precision','industrial','mastery'];
export const upgradeCost=m=>Math.ceil(TYPES[m.type].cost*15*Math.pow(5,m.level-1));
export function upgradeIssue(s,m){if(m.level>=5)return'Niveau maximum atteint.';if(period(s,m)<=STEP)return'Cadence maximale atteinte : 4 cycles par seconde.';const required=upgradeResearch[m.level-1];if(!s.research.includes(required))return'Recherche requise : '+RESEARCH.find(r=>r.id===required).name;const cycles=100*Math.pow(5,m.level-1);if(m.made<cycles)return`Cette machine doit accomplir ${cycles} cycles (${m.made}).`;if(s.gold<upgradeCost(m))return`Il manque ${Math.ceil(upgradeCost(m)-s.gold)} pièces.`;return''}
export function upgrade(s,m){const error=upgradeIssue(s,m);if(error)return error;const cost=upgradeCost(m);s.gold-=cost;m.paid+=cost;m.level++;return null}
export function sell(s,m){const total=m.buf.reduce((n,p)=>n+value(p),0);s.gold+=total;s.counts.sold+=total;m.buf=[];return total}
export function accepts(s,m,p){if(m.buf.length>=capacity(s,m))return false;if(['gold','dust'].includes(m.type))return false;if(m.type==='letter')return p.kind==='dust';if(m.type==='word')return p.kind==='letter';if(m.type==='phrase')return p.kind==='word'&&isWord(p.text)||['phrase','sentence'].includes(p.kind)&&tokens(p).every(isWord);if(['space','punct','validator'].includes(m.type))return ['phrase','sentence'].includes(p.kind);if(m.type==='scanner')return p.kind==='word';if(m.type==='vault')return p.kind==='sentence'&&p.valid;if(['upper','accent','shuffle'].includes(m.type))return p.kind!=='dust';return true}
