export function chosenRecipe(s,m){if(!dictionaryAvailable(s))return null;const known=knownWords(s);if(!known.length)return null;if(m.target!=='auto'){if(!known.includes(m.target))return null;const text=m.target;return{text,indices:recipeIndices(m,text)}}let best=null;for(const w of DICTIONARY.filter(w=>known.includes(w.text))){const ids=recipeIndices(m,w.text);if(ids&&(!best||w.text.length>best.text.length))best={text:w.text,indices:ids}}return best}
export function shortage(s,m){if(!dictionaryAvailable(s))return'Recherchez Recettes mémorisées (1 000 mots produits et un mot découvert).';if(m.target!=='auto'&&!knownWords(s).includes(m.target))return'Ce mot n’est pas découvert. Changez de recette ou étudiez-le au laboratoire.';if(!knownWords(s).length)return'Découvrez ou étudiez un premier mot.';const recipe=chosenRecipe(s,m);if(recipe?.indices)return'';if(m.target==='auto')return'Aucun mot réalisable. Dirigez la presse ou recyclez les surplus.';const have={};m.buf.forEach(p=>have[normalize(p.text)]=(have[normalize(p.text)]||0)+1);const missing={};for(const c of Array.from(m.target)){if(have[c])have[c]--;else missing[c]=(missing[c]||0)+1}return'Manque : '+Object.entries(missing).map(([c,n])=>`${c} ×${n}`).join(' · ')}
function invalidate(p){if(p.kind==='sentence'){p.kind='phrase';p.valid=false}if(p.kind==='word')p.valid=isWord(p.text);return p}
function produce(s,m){if(m.disabled||m.out||m.reject)return false;let p;
 if(m.type==='gold'){s.gold+=8;return true}
 if(m.type==='dust'){s.counts.dust++;p={kind:'dust',text:'░',born:s.time}}
 else if(m.type==='letter'){const n=pressCost(s);if(m.buf.length<n)return false;m.buf.splice(0,n);let pool=m.mode==='vowel'?'aaaeeeeiioouuy':m.mode==='consonant'?'bbbccdddffggghhjklllmmmnnnnppqrrrrssssttttvwxz':'aaaaaaeeeeeeeeiiiiiooooouuubccddffgghjklmmmnnnnppqrrrrrssssssttttttvwxyz';if(s.research.includes('target')&&dictionaryAvailable(s)&&m.target!=='auto'&&knownWords(s).includes(m.target))pool=m.target;p={kind:'letter',text:pool[Math.floor(rng(s)*pool.length)],born:s.time};s.counts.letters++}
 else if(m.type==='word'){let list,text;if(m.mode==='dictionary'){if(!dictionaryAvailable(s))return false;const r=chosenRecipe(s,m);if(!r?.indices){if(m.buf.length>=48){m.reject=m.buf.shift();m.note='Surplus envoyé à droite : connectez un recycleur.';return true}return false}text=r.text;list=r.indices.map(i=>m.buf[i]);m.buf=m.buf.filter((_,i)=>!r.indices.includes(i))}else{if(m.buf.length<m.length)return false;list=m.buf.splice(0,m.length);text=shuffle(s,list.map(p=>p.text).join(''))}p={kind:'word',text,valid:isWord(text),born:Math.min(...list.map(p=>p.born??s.time))};s.counts.words++;if(text.length>s.longestWord.length)s.longestWord=text}
 else if(m.type==='phrase'){const plan=phrasePlan(s,m);if(!plan)return false;const inputs=m.buf.splice(0,plan.n);p={kind:'phrase',tokens:plan.list,text:plan.list.join(''),born:Math.min(...inputs.map(p=>p.born??s.time))}}
 else if(['chest','vault'].includes(m.type)){if(m.storage==='auto'){if(!m.buf.length)return false;sell(s,m);return true}if(m.storage!=='pass'||!m.buf.length)return false;p=m.buf.shift()}
 else {if(!m.buf.length)return false;p={...m.buf.shift()};if(p.tokens)p.tokens=[...p.tokens];
 if(m.type==='recycler')p={kind:'dust',text:'░',born:s.time};
 if(m.type==='scanner'){p.valid=isWord(p.text);if(!p.valid){m.lastResult={...p,value:value(p)};m.reject=p;return true}}
 if(m.type==='space'){p.text=tokens(p).join(' ');invalidate(p)}
 if(m.type==='upper'){p.text=p.text.replace(/\p{L}/u,c=>c.toUpperCase());invalidate(p)}
 if(m.type==='punct'){p.text=p.text.replace(/[.,!?:;]$/u,'')+m.punct;invalidate(p)}
 if(m.type==='shuffle'){p.text=shuffle(s,p.text);if(p.tokens)p.tokens=p.text.split(/\s+/);invalidate(p)}
 if(m.type==='accent'){const map=m.accent==='grave'?{a:'à',e:'è',u:'ù'}:m.accent==='circumflex'?{a:'â',e:'ê',i:'î',o:'ô',u:'û'}:{e:'é'};let done=false;p.text=Array.from(p.text).map(c=>{const l=normalize(c);if(!done&&map[l]){done=true;return c===l?map[l]:map[l].toUpperCase()}return c}).join('');if(p.tokens)p.tokens=p.text.replace(/[.,!?:;]$/,'').split(' ');invalidate(p)}
 if(m.type==='validator'){const v=validation(p,m.mode==='syntax'&&s.research.includes('syntax'),activeTemplate(s,m).id);p={...p,...v,kind:'sentence'};if(!p.valid){m.lastResult={...p,value:value(p)};m.reject=p;m.note='Rejet : '+v.reasons.join(', ');return true}}
 }
 if(p?.kind==='word'&&isWord(p.text)){p.valid=true;if(!p.countedValid){s.counts.validWords++;observe(s,'VALID_WORD_PRODUCED',{text:p.text});p.countedValid=true}if(!s.discovered.includes(normalize(p.text)))s.discovered.push(normalize(p.text))}if(p){enrich(p);if(['word','scanner','validator'].includes(m.type))m.lastResult={...p,value:value(p)};const eventType={dust:'DUST_PRODUCED',letter:'LETTER_PRODUCED',word:'WORD_PRODUCED'}[m.type];if(eventType)observe(s,eventType,{text:p.text})}m.note='';m.out=p;return true;
}
function match(m,p){const t=normalize(p.text);return m.filter==='vowel'?p.kind==='letter'&&'aeiouyàâéèêîôùû'.includes(t):m.filter==='consonant'?p.kind==='letter'&&!('aeiouyàâéèêîôùû'.includes(t)):m.filter==='valid'?p.kind==='word'&&isWord(t):m.filter==='word'?p.kind==='word':m.filter==='custom'?p.kind==='letter'&&m.custom.includes(t):p.kind==='sentence'}
function onReceive(s,m,p){if(m.type!=='vault'||p.kind!=='sentence'||!p.valid||p.archived)return;p.archived=true;s.counts.sentences++;const words=tokens(p).length,chars=Array.from(p.text).length,duration=Math.max(0,s.time-(p.born??s.time)),r={text:p.text,chars,words,duration,at:new Date().toISOString(),uptime:s.time,...scoreSentence(p),estimated:!!s.offlineBatch,value:value(p)};observe(s,'SENTENCE_PRODUCED',{text:p.text,chars,words});s.recent.unshift(p.text);s.recent=s.recent.slice(0,6);if(!s.record||chars>s.record.chars){const old=s.record?.chars||0;s.record=r;if(old&&!s.stats.milestones.recordImproved)s.stats.milestones.recordImproved={seconds:s.time,estimated:!!s.offlineBatch};emit(s,'NEW_RECORD',{title:'Nouveau record',text:`${old} → ${chars} caractères (+${chars-old}) · ${words} mots`,preview:p.text.slice(0,100),old,chars,delta:chars-old})}if(!s.bestValueSentence||r.value>s.bestValueSentence.value)s.bestValueSentence=r;if(!s.offlineBatch&&(!s.fastestSentence||duration<s.fastestSentence.duration))s.fastestSentence=r;if(!s.offlineBatch&&words>=100&&(!s.fastest100||duration<s.fastest100.duration))s.fastest100={duration,words}}
export function outputPorts(m,p,reject=false){let candidates=ports(m).filter(port=>port.kind==='out');if(reject)return candidates.filter(port=>port.channel==='reject');if(m.type==='filter')return candidates.filter(port=>port.channel===(match(m,p)?'main':'other'));candidates=candidates.filter(port=>port.channel==='main');if(['splitter','phrase'].includes(m.type)&&candidates.length>1){const n=m.turn%candidates.length;candidates=[...candidates.slice(n),...candidates.slice(0,n)]}return candidates}
